import {paintFrame,warmFrames} from './frame-cache.js';
import {hydrateMedia} from './item-media.js';
import {MAX_COMPARE,parseCBGLink,frameAt} from './compare-core.js';
import {safeImageURL} from './media.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n==null?'图鉴 · 无售价':'¥'+(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2});
let selected=[];try{const saved=JSON.parse(localStorage.getItem('zx-compare-items')||'[]');if(Array.isArray(saved))selected=saved.filter(i=>i&&typeof i.id==='string'&&typeof i.skin==='string'&&Array.isArray(i.slots)&&i.slots.every(v=>Number.isSafeInteger(v)&&v>=0)&&(Number.isSafeInteger(i.favorites)||i.archive===true)&&(!i.holesCount||Number.isSafeInteger(i.holesCount))&&(Number.isSafeInteger(i.priceCents)||(i.archive===true&&i.priceCents===null))).slice(0,MAX_COMPARE)}catch{}
let batch=window.latestMarketData?.batches.filter(b=>b.coverage!=='failed').at(-1),pool=batch?.items??[],angle=0,scale=2.2,panX=0,panY=0,baseline=selected[0]?.id,importing=false;
const nav=document.createElement('button');nav.className='nav';nav.id='compare-nav';nav.innerHTML='⇄ <span>谪星比较</span><b id="compare-count">0</b>';document.querySelector('nav').append(nav);
const panel=document.createElement('section');panel.id='compare-view';panel.hidden=true;panel.innerHTML='<section class="card"><div class="card-heading"><div><h2>把心仪的谪星，放在一起看</h2><p>最多8件 · 同步角度与缩放 · 使用藏宝阁真实原图</p></div><button type="button" class="button secondary" id="compare-clear">清空比较</button></div><div class="compare-import"><label>粘贴藏宝阁商品链接（每行一个）<textarea id="compare-links" rows="2" placeholder="https://yjwujian.cbg.163.com/cgi/mweb/equip/…"></textarea></label><button type="button" class="button" id="compare-import">加入比较</button></div><p id="compare-message" class="subtle-note" role="status">也可以在行情列表点击“比较”添加商品。</p></section><section class="card compare-controls"><label>同步角度<input id="compare-angle" type="range" min="0" max="360" value="0"></label><label>同步放大<input id="compare-zoom" type="range" min="1" max="6" step="0.1" value="2.2"></label><select id="compare-drag" aria-label="比较拖动模式"><option value="rotate">拖动旋转</option><option value="pan">拖动平移</option></select><label class="compare-check"><input id="compare-guide" type="checkbox">水平辅助线</label><button type="button" class="button secondary" id="compare-bg">切换背景</button><button type="button" class="button secondary" id="compare-reset">还原显示</button><details class="compare-adjust"><summary>显示调整</summary><label>亮度<input id="compare-brightness" type="range" min="0.5" max="1.5" step="0.05" value="1"></label><label>对比度<input id="compare-contrast" type="range" min="0.5" max="1.5" step="0.05" value="1"></label><label>饱和度<input id="compare-saturation" type="range" min="0" max="2" step="0.05" value="1"></label><small>调整只影响当前显示；请还原后判断实际外观颜色。</small></details></section><div id="compare-cards" class="compare-cards"></div><p class="subtle-note">帧序列同步不保证不同商品拍摄姿态完全一致。价格与状态以观察时间及藏宝阁当前页面为准；数值高低不直接等于外观优劣。</p>';
document.querySelector('footer').before(panel);
const tray=document.createElement('button');tray.className='compare-tray button';tray.type='button';document.body.append(tray);tray.onclick=()=>nav.click();
const overlay=document.createElement('section');overlay.className='card tool-form';overlay.innerHTML='<div class="card-heading"><div><h2>前两件叠加检视</h2><p>与上方同步角度与缩放；跨姿态图片可能无法完全对齐。</p></div><label>第二件透明度<input id="compare-opacity" type="range" min="0" max="1" step="0.01" value="0.5"></label></div><div class="compare-stage compare-overlay"><img id="overlay-first" alt="第一件商品叠加图" referrerpolicy="no-referrer"><img id="overlay-second" alt="第二件商品叠加图" referrerpolicy="no-referrer"></div>';$('#compare-cards').after(overlay);$('#compare-opacity').oninput=()=>$('#overlay-second').style.opacity=$('#compare-opacity').value;
function updateTray(){tray.hidden=!selected.length||!panel.hidden;tray.textContent=`⇄ 已选 ${selected.length} 件 · 打开比较`}
new MutationObserver(updateTray).observe(panel,{attributes:true,attributeFilter:['hidden']});
window.addEventListener('add-compare',event=>{if(event.detail?.id&&Array.isArray(event.detail.slots)){const added=add(event.detail);window.dispatchEvent(new CustomEvent('compare-added',{detail:{ok:added,count:selected.length}}))}});
function message(value){$('#compare-message').textContent=value}
function persist(){try{localStorage.setItem('zx-compare-items',JSON.stringify(selected))}catch{message('浏览器无法保存比较列表，本次会话仍可比较。')}}
function open(){document.querySelectorAll('.content>section[id$="-view"]').forEach(el=>el.hidden=el!==panel);document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el===nav));$('#crumb').textContent='谪星比较';$('#page-title').textContent='让差别，一眼可见。';$('#page-description').textContent='同步旋转、放大与并排数值，比较你真正关心的细节。';location.hash='compare';render();for(const item of selected)fillMedia(item)}
nav.onclick=open;document.querySelectorAll('[data-view],#lottery-nav').forEach(button=>button.addEventListener('click',()=>{panel.hidden=true;nav.classList.remove('active');if(!window.portalRouterReady&&location.hash==='#compare')history.replaceState(null,'',location.pathname)}));
function add(item){if(selected.some(i=>i.id===item.id)){message('该商品已经在比较列表中。');return false}if(selected.length>=MAX_COMPARE){message('最多比较8件，请先移除一件。');return false}selected.push({...item,observedAt:item.observedAt??batch?.at??new Date().toISOString()});baseline??=item.id;persist();render();fillMedia(item);message(`已加入 ${item.skin}，共${selected.length}件。`);return true}
async function fillMedia(item){if(item.previewFrames?.length||item.archive)return;try{const full=await hydrateMedia(item),entry=selected.find(i=>i.id===item.id);if(entry){Object.assign(entry,full);persist();if(!panel.hidden)render()}}catch{message('高清原图暂未载入，可稍后重试。')}}
function cardFrames(item){const frames=(Array.isArray(item.previewFrames)?item.previewFrames:[]).map(safeImageURL).filter(Boolean);const thumb=safeImageURL(item.thumbnail);return frames.length?frames:thumb?[thumb]:[]}
function render(){
 $('#compare-count').textContent=selected.length;updateTray();overlay.hidden=selected.length<2;if(panel.hidden)return;const base=selected.find(i=>i.id===baseline)??selected[0];baseline=base?.id;
 $('#compare-cards').innerHTML=selected.map(item=>{const same=base?.skin===item.skin&&(base.holesCount??base.slots.length)===(item.holesCount??item.slots.length),delta=base?item.priceCents-base.priceCents:0;return `<article class="card compare-card" data-id="${esc(item.id)}"><div class="compare-card-head"><strong>${esc(item.skin)}</strong><button type="button" data-remove="${esc(item.id)}" aria-label="移除${esc(item.skin)}">×</button></div><div class="compare-stage" tabindex="0" role="region" aria-label="${esc(item.skin)}外观，方向键切换角度"><img class="compare-image" alt="${esc(item.skin)}外观" referrerpolicy="no-referrer" draggable="false"><div class="compare-image-error" hidden>暂无可用图片</div><div class="compare-horizontal" hidden></div></div><div class="compare-card-info"><div class="compare-price"><strong>${money(item.priceCents)}</strong><span>${item.holesCount??item.slots.length}孔 · ☆ ${item.favorites??'—'}</span></div><div class="slots">${item.slots.map((v,n)=>`<span title="${same&&base.slots[n]!=null?'较基准 '+(v-base.slots[n]):'不同外观或孔数不作数值优劣判断'}">${v}${item.unlocks?.[n]===0?'🔒':''}</span>`).join('')||'<span>无星格</span>'}</div><p>${item.id===baseline?'当前比较基准':same&&item.priceCents!=null&&base.priceCents!=null?`较基准 ${delta>=0?'+':'−'}${money(Math.abs(delta))}`:'不同外观或孔数，分开判断价格'}</p><small>${esc(item.archive?'图鉴来源 · 非在售商品':item.status==='listed'?(item.publicity?'公示期':'观察时在售'):'状态待核实')} · ${new Date(item.observedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}</small><div class="compare-card-actions"><button type="button" data-base="${esc(item.id)}">设为基准</button><button type="button" data-full-preview="${esc(item.id)}">高清检视</button><button type="button" data-fee="${esc(item.id)}" ${item.priceCents==null?'hidden':''}>还价试算</button><a class="compare-source" target="_blank" rel="noopener noreferrer">藏宝阁 ↗</a></div></div></article>`}).join('')||'<div class="card empty compare-empty">尚未加入商品。前往行情列表点击“比较”，或粘贴藏宝阁链接。</div>';
 for(const card of document.querySelectorAll('.compare-card')){
  const item=selected.find(i=>i.id===card.dataset.id),image=card.querySelector('img'),stage=card.querySelector('.compare-stage');image.onerror=()=>{card.querySelector('.compare-image-error').hidden=false};image.onload=()=>{card.querySelector('.compare-image-error').hidden=true};
  const link=card.querySelector('.compare-source');try{parseCBGLink(item.url);link.href=item.url}catch{link.hidden=true}
  let drag=null;stage.onpointerdown=e=>{e.preventDefault();stage.setPointerCapture(e.pointerId);stage.classList.add('is-dragging');drag={x:e.clientX,y:e.clientY,angle,panX,panY}};stage.onpointermove=e=>{if(!drag)return;if($('#compare-drag').value==='rotate'){angle=((drag.angle+(e.clientX-drag.x)*1.4)%360+360)%360;$('#compare-angle').value=angle}else{panX=Math.max(-stage.clientWidth*scale,Math.min(stage.clientWidth*scale,drag.panX+e.clientX-drag.x));panY=Math.max(-stage.clientHeight*scale,Math.min(stage.clientHeight*scale,drag.panY+e.clientY-drag.y))}paint()};stage.onpointerup=stage.onpointercancel=stage.onlostpointercapture=()=>{drag=null;stage.classList.remove('is-dragging');warmFrames(cardFrames(item),Math.round(angle/360*cardFrames(item).length)%Math.max(1,cardFrames(item).length))};stage.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(1,Math.min(6,scale*Math.exp(-e.deltaY*.002)));$('#compare-zoom').value=scale;$('#compare-drag').value='pan';paint()},{passive:false});stage.onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();angle=(angle+(e.key==='ArrowLeft'?-12:12)+360)%360;$('#compare-angle').value=angle;paint()}};
 }
 document.querySelectorAll('[data-full-preview]').forEach(button=>button.onclick=()=>window.dispatchEvent(new CustomEvent('preview-sample',{detail:selected.find(item=>item.id===button.dataset.fullPreview)})));
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected=selected.filter(i=>i.id!==b.dataset.remove);persist();render()});document.querySelectorAll('[data-base]').forEach(b=>b.onclick=()=>{baseline=b.dataset.base;render()});document.querySelectorAll('[data-fee]').forEach(b=>b.onclick=()=>{const item=selected.find(i=>i.id===b.dataset.fee);window.dispatchEvent(new CustomEvent('fee-product',{detail:item.priceCents}))});paint();
}
let paintRaf=0;function paint(){if(!paintRaf)paintRaf=requestAnimationFrame(()=>{paintRaf=0;paintNow()})}
function paintNow(){for(let i=0;i<2;i++){const image=$('#overlay-'+(i?'second':'first')),src=selected[i]?frameAt(cardFrames(selected[i]),angle):null;if(src)paintFrame(image,src);image.hidden=!src;image.style.transform=`translate(${panX}px,${panY}px) scale(${scale})`;}for(const card of document.querySelectorAll('.compare-card')){const item=selected.find(i=>i.id===card.dataset.id),frames=cardFrames(item),src=frameAt(frames,angle),image=card.querySelector('img');image.onerror=()=>{image.dataset.failed=image.dataset.requestedFrame;card.querySelector('.compare-image-error').hidden=false};if(src)paintFrame(image,src);image.hidden=!src;card.querySelector('.compare-image-error').hidden=!!src&&image.dataset.failed!==src;image.style.transform=`translate(${panX}px,${panY}px) scale(${scale})`;image.style.filter=`brightness(${$('#compare-brightness').value}) contrast(${$('#compare-contrast').value}) saturate(${$('#compare-saturation').value})`;card.querySelector('.compare-horizontal').hidden=!$('#compare-guide').checked}}
$('#compare-angle').oninput=()=>{angle=Number($('#compare-angle').value);paint()};$('#compare-zoom').oninput=()=>{scale=Number($('#compare-zoom').value);if(scale===1){panX=0;panY=0}$('#compare-drag').value=scale>1?'pan':'rotate';paint()};for(const id of ['compare-brightness','compare-contrast','compare-saturation','compare-guide'])$('#'+id).oninput=paint;
$('#compare-bg').onclick=()=>$('#compare-cards').classList.toggle('light');$('#compare-reset').onclick=()=>{angle=0;scale=2.2;panX=0;panY=0;$('#compare-angle').value='0';$('#compare-zoom').value='2.2';$('#compare-drag').value='rotate';for(const id of ['brightness','contrast','saturation'])$('#compare-'+id).value='1';paint()};$('#compare-clear').onclick=()=>{selected=[];baseline=null;persist();render();message('比较列表已清空。')};
$('#compare-import').onclick=async()=>{if(importing)return;const links=$('#compare-links').value.split(/\s+/).filter(Boolean);if(!links.length)return message('请先粘贴商品链接。');if(links.length>MAX_COMPARE)return message('一次最多输入8个链接。');importing=true;$('#compare-import').disabled=true;let failures=[];try{for(const link of links){if(selected.length>=MAX_COMPARE){failures.push('比较列表已满');break}try{const identity=parseCBGLink(link);let item=pool.find(i=>i.serverId===identity.serverId&&i.ordersn===identity.ordersn);if(!item){message('正在读取藏宝阁商品…');const r=await fetch('/api/compare/item?'+new URLSearchParams({url:link}),{signal:AbortSignal.timeout(30000)});if(!r.ok){let error;try{error=(await r.json()).error}catch{}throw Error(error||'当前快照未收录该商品；完整本机服务可加载链接')}const data=await r.json();item={...data.item,observedAt:data.observedAt};await new Promise(r=>setTimeout(r,1550))}add(item)}catch(error){failures.push(error.message)}}message(failures.length?`已保留成功加入的商品。${failures.join('；')}`:`加入完成，共${selected.length}件。`)}finally{importing=false;$('#compare-import').disabled=false}};
function attachButtons(){for(const row of document.querySelectorAll('#listings tr[data-id]')){if(row.querySelector('.row-compare'))continue;const button=document.createElement('button');button.type='button';button.className='row-preview row-compare';button.textContent='比较';button.onclick=e=>{e.stopPropagation();const item=pool.find(i=>i.id===row.dataset.id);if(item){add(item);button.textContent='已加入'}};row.lastElementChild.append(button)}}
window.addEventListener('market-rendered',attachButtons);window.addEventListener('market-data',event=>{batch=event.detail.batches.filter(b=>b.coverage!=='failed').at(-1);pool=batch?.items??[];selected=selected.map(item=>{const fresh=pool.find(i=>i.id===item.id);return fresh?{...item,...fresh,previewFrames:fresh.previewFrames?.length?fresh.previewFrames:item.previewFrames,observedAt:batch.at}:item});persist();attachButtons();render()});
attachButtons();render();if(location.hash==='#compare')open();

document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',()=>window.scrollTo({top:0,behavior:'instant'})));
